(* Timers, counters, fault code, phase, takt time and KPI maths of the line.
   The ladder program SmartTextileLadder runs first in every scan and sets the F_R.. flags,
   this program reads them, runs the timers and counters, and gives back the T.._Q done bits. *)

(* R1: Robot fault or robot timeout *)
IF F_R01_RobotFaultRobot THEN D108_FaultCode := 2; END_IF;

(* R2: Inspection timeout (no vision result) *)
IF F_R02_InspectionTimeoutVision THEN D108_FaultCode := 1; END_IF;

(* R3: Index or packaging timeout (jam, no material) *)
IF F_R03_IndexPackagingTimeout THEN D108_FaultCode := 3; END_IF;

(* R4: Unknown product (identification failed) *)
IF F_R04_UnknownProductIdentification THEN D108_FaultCode := 4; END_IF;

(* R5: Emergency stop (chain open or HMI button) *)
IF F_R05_EmergencyStopChain THEN D108_FaultCode := 5; END_IF;

(* R6: Reset: clear faults, E-stop and the line *)
IF F_R06_ResetClearFaults THEN D107_Phase := 0; END_IF;
IF F_R06_ResetClearFaults THEN D108_FaultCode := 0; END_IF;
IF F_R06_ResetClearFaults THEN D110_CycleMs := 0; END_IF;

(* R11: Manual override: product A *)
IF F_R11_ManualOverrideProduct THEN D106_CurrentProduct := 1; END_IF;

(* R12: Manual override: product B *)
IF F_R12_ManualOverrideProduct THEN D106_CurrentProduct := 2; END_IF;

(* R13: Idle start: feed the first product *)
IF F_R13_IdleStartFeed THEN D107_Phase := 20; END_IF;

(* R26: Index to work *)
IF F_R26_IndexWork THEN D107_Phase := 20; END_IF;

(* R27: Feeder at the start of the belt *)
T0_FeedTime(IN := F_R27_FeederStartBelt, PT := T#2000ms);
T0_FeedTime_Q := T0_FeedTime.Q;

(* R29: Identification dwell *)
T8_IdDwell(IN := F_R29_IdentificationDwell, PT := T#500ms);
T8_IdDwell_Q := T8_IdDwell.Q;

(* R30: Identification timeout *)
T9_IdTimeout(IN := F_R30_IdentificationTimeout, PT := T#3000ms);
T9_IdTimeout_Q := T9_IdTimeout.Q;

(* R31: Identify product A (auto mode) *)
IF F_R31_IdentifyProductAuto THEN D106_CurrentProduct := 1; END_IF;

(* R32: Identify product B (auto mode) *)
IF F_R32_IdentifyProductB THEN D106_CurrentProduct := 2; END_IF;

(* R35: Cutter and cutting time *)
T1_CutTime(IN := F_R35_CutterCuttingTime, PT := T#3000ms);
T1_CutTime_Q := T1_CutTime.Q;

(* R38: Finishing time, product A (5 s) *)
T2_FinishA(IN := F_R38_FinishingTimeProduct, PT := T#5000ms);
T2_FinishA_Q := T2_FinishA.Q;

(* R39: Finishing time, product B (8 s) *)
T3_FinishB(IN := F_R39_FinishingTimeProduct, PT := T#8000ms);
T3_FinishB_Q := T3_FinishB.Q;

(* R42: Inspection timeout timer *)
T4_InspTimeout(IN := F_R42_InspectionTimeoutTimer, PT := T#5000ms);
T4_InspTimeout_Q := T4_InspTimeout.Q;

(* R49: Robot watchdog timer *)
T10_RobotWdg(IN := F_R49_RobotWatchdogTimer, PT := T#30000ms);
T10_RobotWdg_Q := T10_RobotWdg.Q;

(* R54: Packaging machine and watchdog *)
T11_PackWdg(IN := F_R54_PackagingMachineWatchdog, PT := T#15000ms);
T11_PackWdg_Q := T11_PackWdg.Q;

(* R59: Work to index *)
IF F_R59_WorkIndex THEN D107_Phase := 10; END_IF;

(* R61: Index watchdog (15 s) *)
T7_IndexWdg(IN := F_R61_IndexWatchdog15, PT := T#15000ms);
T7_IndexWdg_Q := T7_IndexWdg.Q;

(* R62: Stopwatches (add one scan = 20 ms) *)
IF F_R62_StopwatchesAddOne THEN D110_CycleMs := (D110_CycleMs + 20); END_IF;
IF F_R62_StopwatchesAddOne THEN D111_RunMs := (D111_RunMs + 20); END_IF;

(* R63: Takt time of the last product (0.1 s) *)
IF F_R63_TaktTimeLast THEN D104_TaktTime01s := DINT_TO_INT((D110_CycleMs / 100)); END_IF;
IF F_R63_TaktTimeLast THEN D110_CycleMs := 0; END_IF;

(* R64: Good counter *)
C0_GoodCtr(CU := F_R64_GoodCounter, R := F_R71_ClearCountersKPIs, PV := 9999);

(* R65: Reject counter *)
C1_RejectCtr(CU := F_R65_RejectCounter, R := F_R71_ClearCountersKPIs, PV := 9999);

(* R66: Packaged counter *)
C2_PackagedCtr(CU := F_R66_PackagedCounter, R := F_R71_ClearCountersKPIs, PV := 9999);

(* R67: Copy counters to data registers *)
pw := TRUE;
IF pw THEN D100_GoodCount := C0_GoodCtr.CV; END_IF;
IF pw THEN D101_RejectCount := C1_RejectCtr.CV; END_IF;
IF pw THEN D109_PackagedCount := C2_PackagedCtr.CV; END_IF;

(* R68: Total count *)
pw := TRUE;
IF pw THEN D102_TotalCount := DINT_TO_INT((INT_TO_DINT(D100_GoodCount) + INT_TO_DINT(D101_RejectCount))); END_IF;

(* R69: Defect percentage x100 *)
pw := (D102_TotalCount > 0);
IF pw THEN D103_DefectPctX100 := DINT_TO_INT(((INT_TO_DINT(D101_RejectCount) * 10000) / INT_TO_DINT(D102_TotalCount))); END_IF;

(* R70: Production rate: average products per minute x10 *)
pw := (D111_RunMs >= 100);
IF pw THEN D105_RateX10PerMin := DINT_TO_INT(((INT_TO_DINT(D102_TotalCount) * 6000) / (D111_RunMs / 100))); END_IF;

(* R71: Clear counters and KPIs (HMI) *)
IF F_R71_ClearCountersKPIs THEN D103_DefectPctX100 := 0; END_IF;
IF F_R71_ClearCountersKPIs THEN D104_TaktTime01s := 0; END_IF;
IF F_R71_ClearCountersKPIs THEN D105_RateX10PerMin := 0; END_IF;
IF F_R71_ClearCountersKPIs THEN D110_CycleMs := 0; END_IF;
IF F_R71_ClearCountersKPIs THEN D111_RunMs := 0; END_IF;
